import math


def point_distance(x1: int, y1: int, x2: int, y2: int) -> float:
    return math.sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2))


x1, y1, x2, y2 = map(int, input().split())
print(f"{point_distance(x1, y1, x2, y2):.2f}")

