go.solution:
package main

import (
	"fmt"
	"math"
)

func pointDistance(x1 int, y1 int, x2 int, y2 int) float64 {
	dx := float64(x2 - x1)
	dy := float64(y2 - y1)
	return math.Sqrt(math.Pow(dx, 2) + math.Pow(dy, 2))
}

func main() {
	var x1, y1, x2, y2 int
	fmt.Scan(&x1, &y1, &x2, &y2)
	fmt.Printf("%.2f\n", pointDistance(x1, y1, x2, y2))
}
